WITH matched_keys AS (SELECT account_type, status FROM accounts EXCEPT ALL SELECT account_type, status FROM accounts WHERE opened_date < '2024-12-01'), kept_rows AS (SELECT s.* FROM accounts s JOIN matched_keys k ON s.account_type = k.account_type AND s.status = k.status) SELECT customer_id, AVG(balance) FILTER (WHERE account_type = 'CHECKING') AS checking_avg_balance, STDDEV_SAMP(balance) AS balance_stddev, PERCENTILE_APPROX(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, PERCENTILE_APPROX(balance, 0.9) AS balance_p90, STDDEV_SAMP(balance) AS balance_stddev_2, STDDEV_SAMP(balance) AS balance_stddev_3 FROM kept_rows GROUP BY customer_id ORDER BY balance_stddev_2 DESC;
